<?php
defined('ABSPATH') || exit;
final class MUTQAN_Chat_Upload {
 public static function init(){add_action('rest_api_init',array(__CLASS__,'rest'));}
 public static function rest(){register_rest_route('mutqan/v1','/orders/(?P<id>\d+)/messages/upload',array('methods'=>'POST','permission_callback'=>function($r){return MUTQAN_Communications::participants((int)$r['id']);},'callback'=>function($r){$id=(int)$r['id'];if(empty($_FILES['file']))return new WP_Error('missing_file','الملف مطلوب.',array('status'=>400));require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';$f=$_FILES['file'];if((int)$f['size']>10*1024*1024)return new WP_Error('file_too_large','الحد الأقصى 10MB.',array('status'=>413));$allowed=array('image/jpeg','image/png','image/webp','application/pdf','audio/mpeg','audio/ogg','audio/webm');$mime=sanitize_mime_type($f['type']);if(!in_array($mime,$allowed,true))return new WP_Error('invalid_file','نوع الملف غير مسموح.',array('status'=>400));$over=array('test_form'=>false,'mimes'=>array('jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','pdf'=>'application/pdf','mp3'=>'audio/mpeg','ogg'=>'audio/ogg','webm'=>'audio/webm'));$up=wp_handle_upload($f,$over);if(isset($up['error']))return new WP_Error('upload_failed',$up['error'],array('status'=>500));$aid=wp_insert_attachment(array('post_mime_type'=>$up['type'],'post_title'=>sanitize_file_name(pathinfo($f['name'],PATHINFO_FILENAME)),'post_status'=>'inherit','post_author'=>get_current_user_id()),$up['file']);if(is_wp_error($aid))return $aid;$type=strpos($mime,'image/')===0?'image':(strpos($mime,'audio/')===0?'voice':'file');$msg=MUTQAN_Communications::send($id,$type,'',$aid);if(is_wp_error($msg))return $msg;return rest_ensure_response(array('ok'=>true,'message_id'=>$msg,'attachment_id'=>$aid,'url'=>wp_get_attachment_url($aid)));}));}
}
MUTQAN_Chat_Upload::init();
